import sys
import threading


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    DIV = "#DIV/0!"
    CYC = "#CYCLE!"

    def tokenize(s):
        toks = []
        i, n = 0, len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                toks.append(('num', int(s[i:j])))
                i = j
            elif ch.isalpha():
                j = i
                while j < n and s[j].isalpha():
                    j += 1
                k = j
                while k < n and s[k].isdigit():
                    k += 1
                if k > j:
                    toks.append(('cell', s[i:k].upper()))
                else:
                    toks.append(('name', s[i:j].upper()))
                i = k
            elif ch in '<>':
                if i + 1 < n and s[i + 1] in '=>' and not (ch == '>' and s[i + 1] == '>'):
                    toks.append(('op', s[i:i + 2]))
                    i += 2
                else:
                    toks.append(('op', ch))
                    i += 1
            else:
                toks.append(('op', ch))
                i += 1
        toks.append(('end', None))
        return toks

    def parse(s):
        toks = tokenize(s)
        pos = [0]

        def peek(o=0):
            return toks[pos[0] + o]

        def nxt():
            t = toks[pos[0]]
            pos[0] += 1
            return t

        def expect(v):
            t = nxt()
            assert t[1] == v, (t, v)

        def expr():
            node = term()
            while peek()[0] == 'op' and peek()[1] in ('+', '-'):
                op = nxt()[1]
                node = ('bin', op, node, term())
            return node

        def term():
            node = unary()
            while peek()[0] == 'op' and peek()[1] in ('*', '/'):
                op = nxt()[1]
                node = ('bin', op, node, unary())
            return node

        def unary():
            if peek()[0] == 'op' and peek()[1] == '-':
                nxt()
                return ('neg', unary())
            return atom()

        def atom():
            t = nxt()
            if t[0] == 'num':
                return ('n', t[1])
            if t[0] == 'cell':
                return ('c', t[1])
            if t[0] == 'op' and t[1] == '(':
                e = expr()
                expect(')')
                return e
            if t[0] == 'name':
                fname = t[1]
                expect('(')
                if fname == 'IF':
                    l = expr()
                    op = nxt()[1]
                    r = expr()
                    expect(',')
                    th = expr()
                    expect(',')
                    el = expr()
                    expect(')')
                    return ('if', op, l, r, th, el)
                args = []
                while True:
                    if peek()[0] == 'cell' and peek(1)[0] == 'op' and peek(1)[1] == ':':
                        a = nxt()[1]
                        nxt()
                        b = nxt()[1]
                        c1, r1 = ord(a[0]), int(a[1:])
                        c2, r2 = ord(b[0]), int(b[1:])
                        args.append(('r', min(c1, c2), max(c1, c2), min(r1, r2), max(r1, r2)))
                    else:
                        args.append(expr())
                    t2 = nxt()
                    if t2[1] == ')':
                        break
                return ('f', fname, args)
            raise ValueError("bad token %r" % (t,))

        return expr()

    values = {}
    state = {}  # name -> 1 in progress, 2 done

    def cell_value(name):
        if name not in cells:
            return 0
        st = state.get(name)
        if st == 2:
            return values[name]
        if st == 1:
            return CYC
        state[name] = 1
        content = cells[name].strip()
        if content.startswith('='):
            v = ev(parse(content[1:]))
        else:
            v = int(content)
        values[name] = v
        state[name] = 2
        return v

    def ev(node):
        k = node[0]
        if k == 'n':
            return node[1]
        if k == 'c':
            return cell_value(node[1])
        if k == 'neg':
            v = ev(node[1])
            if isinstance(v, str):
                return v
            return -v
        if k == 'bin':
            a = ev(node[2])
            if isinstance(a, str):
                return a
            b = ev(node[3])
            if isinstance(b, str):
                return b
            op = node[1]
            if op == '+':
                return a + b
            if op == '-':
                return a - b
            if op == '*':
                return a * b
            if b == 0:
                return DIV
            q = abs(a) // abs(b)
            return -q if (a < 0) != (b < 0) else q
        if k == 'if':
            _, op, l, r, th, el = node
            a = ev(l)
            if isinstance(a, str):
                return a
            b = ev(r)
            if isinstance(b, str):
                return b
            if op == '=':
                c = a == b
            elif op == '<>':
                c = a != b
            elif op == '<':
                c = a < b
            elif op == '<=':
                c = a <= b
            elif op == '>':
                c = a > b
            else:
                c = a >= b
            return ev(th if c else el)
        if k == 'f':
            fname, args = node[1], node[2]
            vals = []
            for arg in args:
                if arg[0] == 'r':
                    _, c1, c2, r1, r2 = arg
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            nm = chr(c) + str(r)
                            if nm in cells:
                                v = cell_value(nm)
                                if isinstance(v, str):
                                    return v
                                vals.append(v)
                else:
                    v = ev(arg)
                    if isinstance(v, str):
                        return v
                    vals.append(v)
            if fname == 'SUM':
                return sum(vals)
            if not vals:
                return 0
            if fname == 'MIN':
                return min(vals)
            return max(vals)
        raise ValueError("bad node")

    result = {}
    err = []

    def run():
        try:
            for name in cells:
                result[name] = cell_value(name)
        except BaseException as e:
            err.append(e)

    old_limit = sys.getrecursionlimit()
    sys.setrecursionlimit(1000000)
    old_stack = threading.stack_size()
    try:
        threading.stack_size(512 * 1024 * 1024)
        t = threading.Thread(target=run)
        t.start()
        t.join()
    finally:
        threading.stack_size(old_stack)
        sys.setrecursionlimit(old_limit)
    if err:
        raise err[0]
    return result
